mapper.select:
SELECT COUNT(1)
FROM sys_user
WHERE phone = #{phone}
  AND id <> #{excludeId}
  AND deleted = 0

SELECT COUNT(1)
FROM sys_user
WHERE username = #{username}
  AND id <> #{excludeId}
  AND deleted = 0

SELECT DISTINCT u.id, u.phone, u.password_hash, u.username, u.nickname, u.email, u.gender, u.avatar_code, u.avatar_url, u.department_id, u.status, u.create_time, u.update_time, u.create_by, u.update_by, u.deleted FROM sys_user u
INNER JOIN sys_user_role ur ON ur.user_id = u.id AND ur.deleted = 0 INNER JOIN sys_role r ON r.id = ur.role_id AND r.deleted = 0 AND r.enabled = 1
WHERE u.deleted = 0
AND (u.phone LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
AND u.department_id = #{departmentId}
AND r.code = #{roleCode}
AND u.status = #{status}
ORDER BY u.create_time DESC, u.id DESC
